create or replace function validate_schedule_building_transfer_v1() returns trigger language plpgsql security definer set search_path=public as $$declare nb uuid;ob uuid;req smallint;avail smallint;prof uuid;r record;begin if not new.active or new.classroom_id is null then return new;end if;select building_id into nb from classrooms where id=new.classroom_id and active;if nb is null then return new;end if;select id into prof from schedule_time_profiles where active and tenant_row_allowed(institution_code) limit 1;if prof is null then return new;end if;for r in select ts.period,ts.classroom_id from teacher_schedule ts where ts.active and ts.teacher_id=new.teacher_id and ts.weekday=new.weekday and ts.id<>coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid) and ts.classroom_id is not null and ts.period in(new.period-1,new.period+1) loop select building_id into ob from classrooms where id=r.classroom_id and active;if ob is null or ob=nb then continue;end if;req:=get_schedule_building_travel_minutes_v1(ob,nb);if r.period=new.period-1 then select minutes into avail from schedule_period_breaks where time_profile_id=prof and after_period=r.period and tenant_row_allowed(institution_code);else select minutes into avail from schedule_period_breaks where time_profile_id=prof and after_period=new.period and tenant_row_allowed(institution_code);end if;if coalesce(avail,0)<req then raise exception 'BUILDING_TRANSFER_TIME_INSUFFICIENT';end if;end loop;return new;end$$;
drop trigger if exists trg_validate_schedule_building_transfer_v1 on teacher_schedule;create trigger trg_validate_schedule_building_transfer_v1 before insert or update on teacher_schedule for each row execute function validate_schedule_building_transfer_v1();